// DEV_RIO_201 Distribution — dry-run。UTM付きリンクを組み立て、下書き準備まで。
// design/REVENUE_LOOP_MVP.md(UTM) / ID_AND_IDEMPOTENCY_POLICY.md 準拠。公開はしない。
const i = $input.first().json;
const experiment_id = i.experiment_id ?? 'exp-001';
const theme = i.theme ?? 'store-ai';
const variant = i.variant ?? 'a';
const utm = `utm_source=note&utm_medium=organic&utm_campaign=${theme}-${experiment_id}&utm_content=${variant}`;
const brand_url = i.brand_url ?? 'https://brain-market.com/u/ai_store_yuya/a/b1MTM1UjMgoTZsNWa0JXY';
return [{ json: {
  content_id: i.content_id ?? 'ca-note-001',
  threads_post: i.threads_post ?? '雑務、AIに投げてます。手順はnoteに（プロフから）。',
  note_draft_body: i.note_draft_body ?? '（note本文サンプル）… 末尾CTA↓',
  brain_link_with_utm: `${brand_url}?${utm}`,
  account_id: 'ai_store_lab',
  platform: 'threads',
  action_type: 'prepare_distribution'
} }];

// 冪等性キー付与＋公開直前で停止（外部アクションなし）。
const o = $input.first().json;
const execId = $execution?.id ?? 'dryrun';
const content_asset_id = o.content_id;
const idempotency_key = [o.account_id, o.platform, content_asset_id, o.action_type].join('|');
return [{ json: { ...o, idempotency_key, state: 'WAITING_APPROVAL', published: false,
  note: 'dry-run。Threads投稿候補・note下書き・UTMリンクを準備。★公開・投稿はしない（人間Yes後にBrowser Useで下書き入力→公開は別途Yes）。' } }];
